class TestTaskComplexityClassification:
    """Unit tests for TaskComplexity classification logic."""

    def test_complexity_enum_values(self):
        """Verify TaskComplexity enum has expected values."""
        assert TaskComplexity.TRIVIAL.value == "trivial"
        assert TaskComplexity.STANDARD.value == "standard"
        assert TaskComplexity.COMPLEX.value == "complex"
        assert TaskComplexity.CRITICAL.value == "critical"

    def test_complexity_ordering(self):
        """Verify complexity levels have correct ordering."""
        complexity_order = [
            TaskComplexity.TRIVIAL,
            TaskComplexity.STANDARD,
            TaskComplexity.COMPLEX,
            TaskComplexity.CRITICAL,
        ]
        for i in range(len(complexity_order) - 1):
            assert complexity_order[i] < complexity_order[i + 1]

    @pytest.mark.parametrize(
        "payload,expected_complexity",
        [
            ({"data": "simple"}, TaskComplexity.TRIVIAL),
            ({"data": "x" * 100}, TaskComplexity.STANDARD),
            ({"data": "x" * 1000, "nested": {"deep": "structure"}}, TaskComplexity.COMPLEX),
            ({"data": "x" * 10000, "critical": True}, TaskComplexity.CRITICAL),
        ],
    )
    def test_classify_complexity(self, arbiter_instance, payload, expected_complexity):
        """Test complexity classification based on payload characteristics."""
        task = Task(
            task_id="test_classify",
            name="Classification Test",
            priority=TaskPriority.MEDIUM,
            complexity=TaskComplexity.STANDARD,
            payload=payload,
        )
        classified = arbiter_instance._classify_complexity(task)
        assert classified == expected_complexity

    def test_complexity_override(self, arbiter_instance):
        """Test that explicit complexity overrides automatic classification."""
        task = Task(
            task_id="override_test",
            name="Override Test",
            priority=TaskPriority.HIGH,
            complexity=TaskComplexity.CRITICAL,
            payload={"data": "simple"},
        )
        assert task.complexity == TaskComplexity.CRITICAL


