class TestPriorityQueueOrdering:
    """Tests for priority queue ordering and heap invariants."""

    def test_priority_ordering(self, arbiter_instance, sample_tasks, high_priority_tasks):
        """Verify high-priority tasks are dequeued first."""
        for task in sample_tasks + high_priority_tasks:
            arbiter_instance.submit_task(task)

        dequeued = []
        while not arbiter_instance.is_empty():
            dequeued.append(arbiter_instance.get_next_task())

        # All high-priority tasks should come before medium-priority tasks
        high_indices = [i for i, t in enumerate(dequeued) if t.priority == TaskPriority.HIGH]
        medium_indices = [i for i, t in enumerate(dequeued) if t.priority == TaskPriority.MEDIUM]

        assert high_indices and medium_indices
        assert max(high_indices) < min(medium_indices)

    def test_heap_invariant(self, arbiter_instance, sample_tasks):
        """Verify heap property is maintained after operations."""
        for task in sample_tasks:
            arbiter_instance.submit_task(task)

        # Extract internal heap and verify invariant
        heap = arbiter_instance._task_heap
        for i in range(len(heap)):
            left = 2 * i + 1
            right = 2 * i + 2
            if left < len(heap):
                assert heap[i] <= heap[left], f"Heap invariant violated at index {i}"
            if right < len(heap):
                assert heap[i] <= heap[right], f"Heap invariant violated at index {i}"

    def test_fifo_stability_equal_priority(self, arbiter_instance):
        """Verify FIFO ordering for tasks with equal priority."""
        tasks = [
            Task(
                task_id=f"fifo_{i}",
                name=f"FIFO Task {i}",
                priority=TaskPriority.MEDIUM,
                complexity=TaskComplexity.STANDARD,
                payload={"sequence": i},
            )
            for i in range(20)
        ]

        for task in tasks:
            arbiter_instance.submit_task(task)

        dequeued = []
        while not arbiter_instance.is_empty():
            dequeued.append(arbiter_instance.get_next_task())

        # Verify sequence order is preserved
        sequences = [t.payload["sequence"] for t in dequeued]
        assert sequences == sorted(sequences)

    def test_priority_tie_break_by_timestamp(self, arbiter_instance):
        """Verify timestamp-based tie-breaking for same priority."""
        task1 = Task(
            task_id="tie_1",
            name="Tie Task 1",
            priority=TaskPriority.HIGH,
            complexity=TaskComplexity.STANDARD,
            payload={},
        )
        task2 = Task(
            task_id="tie_2",
            name="Tie Task 2",
            priority=TaskPriority.HIGH,
            complexity=TaskComplexity.STANDARD,
            payload={},
        )

        arbiter_instance.submit_task(task1)
        time.sleep(0.01)  # Ensure different timestamps
        arbiter_instance.submit_task(task2)

        first = arbiter_instance.get_next_task()
        second = arbiter_instance.get_next_task()

        assert first.task_id == "tie_1"
        assert second.task_id == "tie_2"


