class TestPropertyBased:
    """Property-based testing for invariants."""

    def test_heap_invariant_property(self, arbiter_instance):
        """Property: Heap invariant maintained after random operations."""
        import random

        random.seed(42)
        for i in range(100):
            task = Task(
                task_id=f"prop_{i}",
                name=f"Property Task {i}",
                priority=random.choice(list(TaskPriority)),
                complexity=random.choice(list(TaskComplexity)),
                payload={"random": random.random()},
            )
            arbiter_instance.submit_task(task)

        # Verify heap invariant
        heap = arbiter_instance._task_heap
        for i in range(len(heap)):
            left = 2 * i + 1
            right = 2 * i + 2
            if left < len(heap):
                assert heap[i] <= heap[left]
            if right < len(heap):
                assert heap[i] <= heap[right]

    def test_set_uniqueness_property(self, arbiter_instance):
        """Property: No duplicate task IDs in the system."""
        import random

        random.seed(123)
        task_ids = set()

        for i in range(50):
            task_id = f"unique_{random.randint(0, 100)}"
            task = Task(
                task_id=task_id,
                name=f"Task {i}",
                priority=TaskPriority.MEDIUM,
                complexity=TaskComplexity.STANDARD,
                payload={},
            )
            if arbiter_instance.submit_task(task):
                task_ids.add(task_id)

        # Verify no duplicates in internal structures
        assert len(task_ids) == arbiter_instance.get_pending_count()

    def test_fifo_stability_property(self, arbiter_instance):
        """Property: FIFO ordering preserved for equal priority tasks."""
        import random

        random.seed(456)
        tasks = []
        for i in range(30):
            task = Task(
                task_id=f"fifo_prop_{i}",
                name=f"FIFO Property {i}",
                priority=TaskPriority.LOW,
                complexity=TaskComplexity.TRIVIAL,
                payload={"sequence": i},
            )
            tasks.append(task)

        # Shuffle and submit
        random.shuffle(tasks)
        for task in tasks:
            arbiter_instance.submit_task(task)

        # Dequeue and verify sequence
        dequeued = []
        while not arbiter_instance.is_empty():
            dequeued.append(arbiter_instance.get_next_task())

        sequences = [t.payload["sequence"] for t in dequeued]
        assert sequences == sorted(sequences)

    def test_count_invariant_property(self, arbiter_instance):
        """Property: Task count consistency across operations."""
        import random

        random.seed(789)
        submitted = 0
        completed = 0

        for i in range(50):
            action = random.choice(["submit", "complete"])
            if action == "submit":
                task = Task(
                    task_id=f"count_{i}",
                    name=f"Count Task {i}",
                    priority=TaskPriority.MEDIUM,
                    complexity=TaskComplexity.STANDARD,
                    payload={},
                )
                if arbiter_instance.submit_task(task):
                    submitted += 1
            elif not arbiter_instance.is_empty():
                task = arbiter_instance.get_next_task()
                if task:
                    arbiter_instance.complete_task(task.task_id)
                    completed += 1

        assert arbiter_instance.get_pending_count() == submitted - completed


