# LOGGING AND OBSERVABILITY TESTS
# ============================================================

class TestObservability:
    """Tests for logging and observability features."""

    def test_logging_on_submission(self, arbiter_instance, caplog):
        """Verify logging on task submission."""
        with caplog.at_level(logging.INFO):
            task = Task(
                task_id="log_test",
                name="Log Test",
                priority=TaskPriority.MEDIUM,
                complexity=TaskComplexity.STANDARD,
                payload={},
            )
            arbiter_instance.submit_task(task)

        assert any("submit" in record.message.lower() for record in caplog.records)

    def test_logging_on_completion(self, arbiter_instance, caplog):
        """Verify logging on task completion."""
        task = Task(
            task_id="log_complete",
            name="Log Complete",
            priority=TaskPriority.MEDIUM,
            complexity=TaskComplexity.STANDARD,
            payload={},
        )
        arbiter_instance.submit_task(task)
        next_task = arbiter_instance.get_next_task()

        with caplog.at_level(logging.INFO):
            arbiter_instance.complete_task(next_task.task_id)

        assert any("complete" in record.message.lower() for record in caplog.records)

    def test_metrics_collection(self, arbiter_instance):
        """Verify metrics are collected."""
        for i in range(10):
            task = Task(
                task_id=f"metrics_{i}",
                name=f"Metrics Task {i}",
                priority=TaskPriority.MEDIUM,
                complexity=TaskComplexity.STANDARD,
                payload={},
            )
            arbiter_instance.submit_task(task)

        metrics = arbiter_instance.get_metrics()
        assert metrics["total_submitted"] == 10
        assert metrics["pending"] == 10
        assert metrics["completed"] == 0


